//! 供 Ink / 测试直接调用的库入口；本 crate 不提供命令行可执行文件。
//!
//! 本 crate 只负责把 WebGAL 项目编译成 [`plan::Plan`]; 真正的渲染由
//! `webgal-video-render-sys` 静态链接进来的 C++ 库完成, 两者之间不经过 JSON 文件。

use std::path::{Path, PathBuf};

use crate::{
    Result,
    config::ExportConfig,
    plan,
    project::Project,
    script::{self, ChoicePolicy, StartOptions},
};

/// 一次导出的项目与编排参数（编码/输出参数在渲染阶段给）。
#[derive(Debug, Clone)]
pub struct ExportOptions {
    pub project_root: PathBuf,
    pub start_scene: Option<String>,
    pub start_label: Option<String>,
    pub config: ExportConfig,
}

impl ExportOptions {
    /// 默认配置；Ink 后续在此基础上覆盖分辨率、帧率等字段。
    pub fn new(project_root: impl Into<PathBuf>) -> Self {
        Self {
            project_root: project_root.into(),
            start_scene: None,
            start_label: None,
            config: ExportConfig::default(),
        }
    }
}

/// 分析项目，返回场景、选项、缺失资源与不支持项。
pub fn analyze_project(project_root: &Path) -> Result<script::Inspection> {
    let project = Project::open(project_root)?;
    Ok(script::inspect(&project))
}

/// 只编译 plan，不启动渲染器。
pub fn build_plan(options: &ExportOptions) -> Result<plan::Plan> {
    let project = Project::open(&options.project_root)?;
    let mut config = options.config.clone();
    if config.video.auto_width {
        // 界面只提供 720p/1080p/1440p/2160p; 宽度跟随舞台宽高比, 避免拉伸构图。
        let (stage_w, stage_h) = project.stage_size();
        config.video.width = output_width(config.video.height, stage_w, stage_h);
    }
    let policy = ChoicePolicy::new(&config.choices);
    let start = StartOptions {
        scene: options.start_scene.clone(),
        label: options.start_label.clone(),
    };
    let mut plan = script::compile_with(&project, &config, &policy, &start)?;
    plan.meta.ui = config.layers.ui;
    plan.meta.output_w = config.video.width;
    plan.meta.output_h = config.video.height;
    apply_layer_filters(&mut plan, &config);
    let speed = options.config.playback_speed;
    if speed > 0.0 && (speed - 1.0).abs() > f32::EPSILON {
        scale_time(&mut plan, speed);
    }
    Ok(plan)
}

/// 按导出配置裁剪图层。
///
/// 编译阶段仍然完整遍历脚本：文本时长、BGM 起止和 `wait` 都会影响时间线，
/// 不能因为某一层不导出就跳过。这里在计划完成后统一裁掉不输出的内容。
fn apply_layer_filters(plan: &mut plan::Plan, config: &ExportConfig) {
    if !config.layers.background {
        plan.background.clear();
    }
    if !config.layers.figures {
        plan.figures.clear();
    }
    if !config.layers.ui {
        plan.texts.clear();
        plan.choices.clear();
        plan.intros.clear();
    }
    if !config.include_audio {
        plan.audio.clear();
    }
}

/// 由目标高度与舞台宽高比推导输出宽度; 结果取偶数 (H.264 的 yuv420p 要求)。
pub fn output_width(height: u32, stage_width: u32, stage_height: u32) -> u32 {
    if height == 0 || stage_width == 0 || stage_height == 0 {
        return 0;
    }
    let width = (u64::from(height) * u64::from(stage_width) + u64::from(stage_height) / 2)
        / u64::from(stage_height);
    (width as u32) & !1
}

/// 路线节点；UI 用它展示 scene/choose/call。
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RouteNode {
    pub kind: String,
    pub scene: String,
    pub line: usize,
    pub target: Option<String>,
    pub options: Vec<String>,
    pub selected: Option<usize>,
    pub blocked: bool,
}

#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RoutePreview {
    pub nodes: Vec<RouteNode>,
    pub complete: bool,
    pub stop_reason: Option<String>,
}

/// 预览从 start_scene 出发的路线；selected 键为 `scene:line`。
/// 未配置的 choose 会生成 blocked 节点并停止；callScene 只记录，不展开。
pub fn route_preview(
    project_root: &Path,
    start_scene: &str,
    selected: &std::collections::BTreeMap<String, usize>,
) -> Result<RoutePreview> {
    use webgal_language_core::sentence::Sentence;
    let project = Project::open(project_root)?;
    let mut scene_name = start_scene.to_owned();
    let mut line = 0usize;
    let mut nodes = Vec::new();
    let mut complete = false;
    let mut stop_reason = None;
    for _ in 0..512 {
        let Some(entry) = project.scene(&scene_name) else {
            stop_reason = Some(format!("场景不存在: {scene_name}"));
            break;
        };
        let sentences: Vec<_> = entry.sentences().collect();
        if line >= sentences.len() {
            complete = true;
            break;
        }
        let (line_number, info) = sentences[line];
        match &info.sentence {
            Sentence::Choose(choose) => {
                let key = format!("{scene_name}:{line_number}");
                let selection = selected
                    .get(&key)
                    .copied()
                    .filter(|index| *index < choose.choices.len());
                let options = choose
                    .choices
                    .iter()
                    .map(|choice| choice.prompt.clone())
                    .collect();
                let target = selection
                    .and_then(|index| choose.choices.get(index))
                    .and_then(|choice| choice.target.clone());
                let blocked = selection.is_none();
                nodes.push(RouteNode {
                    kind: "choose".to_owned(),
                    scene: scene_name.clone(),
                    line: line_number,
                    target: target.clone(),
                    options,
                    selected: selection,
                    blocked,
                });
                if blocked {
                    stop_reason = Some("choose".to_owned());
                    break;
                }
                match target {
                    Some(target) => {
                        if project.scene(&target).is_some() {
                            scene_name = target;
                            line = 0;
                        } else {
                            line = label_line(entry, &target).unwrap_or(line + 1);
                        }
                    }
                    None => line += 1,
                }
            }
            Sentence::ChangeScene(change) => {
                nodes.push(RouteNode {
                    kind: "changeScene".to_owned(),
                    scene: scene_name.clone(),
                    line: line_number,
                    target: Some(change.scene.clone()),
                    options: Vec::new(),
                    selected: None,
                    blocked: false,
                });
                scene_name = change.scene.clone();
                line = 0;
            }
            Sentence::CallScene(call) => {
                nodes.push(RouteNode {
                    kind: "callScene".to_owned(),
                    scene: scene_name.clone(),
                    line: line_number,
                    target: Some(call.scene.clone()),
                    options: Vec::new(),
                    selected: None,
                    blocked: false,
                });
                line += 1;
            }
            Sentence::End(_) => {
                complete = true;
                break;
            }
            _ => line += 1,
        }
    }
    Ok(RoutePreview {
        nodes,
        complete,
        stop_reason,
    })
}

fn label_line(entry: &crate::project::SceneEntry, label: &str) -> Option<usize> {
    use webgal_language_core::sentence::Sentence;
    entry
        .sentences()
        .find_map(|(line, info)| match &info.sentence {
            Sentence::Label(value) if value.label == label => Some(line - 1),
            _ => None,
        })
}

/// 按播放速度缩短整条时间线。
///
/// 时间戳、淡入淡出、以及文字逐字显示的速度都按同一系数缩放, 否则加速后对话会
/// 在还没显示完时被切掉。
fn scale_time(plan: &mut plan::Plan, speed: f32) {
    fn us(value: u64, speed: f32) -> u64 {
        (value as f64 / f64::from(speed)).round() as u64
    }
    fn ms(value: u32, speed: f32) -> u32 {
        (f64::from(value) / f64::from(speed)).round() as u32
    }

    plan.meta.duration_us = us(plan.meta.duration_us, speed);

    for asset in plan.assets.values_mut() {
        if let Some(duration) = asset.duration_us {
            asset.duration_us = Some(us(duration, speed));
        }
    }

    for key in &mut plan.background {
        key.t_us = us(key.t_us, speed);
        key.enter_ms = ms(key.enter_ms, speed);
        key.exit_ms = ms(key.exit_ms, speed);
    }

    for key in &mut plan.stage {
        key.t_us = us(key.t_us, speed);
        key.enter_ms = ms(key.enter_ms, speed);
    }

    for track in &mut plan.figures {
        for key in &mut track.keys {
            key.t_us = us(key.t_us, speed);
            key.enter_ms = ms(key.enter_ms, speed);
            key.exit_ms = ms(key.exit_ms, speed);
        }
        for pose in &mut track.poses {
            pose.t_us = us(pose.t_us, speed);
        }
    }

    for segment in &mut plan.texts {
        segment.start_us = us(segment.start_us, speed);
        segment.end_us = us(segment.end_us, speed);
        segment.reveal_ms_per_char = ms(segment.reveal_ms_per_char, speed);
        segment.fade_ms = ms(segment.fade_ms, speed);
    }

    for segment in &mut plan.choices {
        segment.start_us = us(segment.start_us, speed);
        segment.end_us = us(segment.end_us, speed);
    }

    for segment in &mut plan.intros {
        segment.start_us = us(segment.start_us, speed);
        segment.end_us = us(segment.end_us, speed);
    }

    for segment in &mut plan.videos {
        segment.start_us = us(segment.start_us, speed);
        segment.end_us = us(segment.end_us, speed);
    }

    for event in &mut plan.audio {
        event.start_us = us(event.start_us, speed);
        event.end_us = event.end_us.map(|value| us(value, speed));
        event.fade_in_ms = ms(event.fade_in_ms, speed);
        event.fade_out_ms = ms(event.fade_out_ms, speed);
    }
}
